public static class VocabularyTopicData
{
    public sealed class Word
    {
        public string Text;
        public string Meaning;
        public string Example;
        public string[] AdditionalExamples;
        public string PartOfSpeech;

        public Word(string text, string meaning, string example, params string[] additionalExamples)
        {
            Text = text;
            Meaning = meaning;
            Example = example;
            AdditionalExamples = additionalExamples;
            PartOfSpeech = InferPartOfSpeech(text, example);
        }
    }

    public sealed class Topic
    {
        public string Id;
        public string DisplayName;
        public Word[] Words;

        internal Topic(string id, string displayName, Word[] words)
        {
            Id = id;
            DisplayName = displayName;
            Words = words;
        }
    }

