    private static readonly Dictionary<string, Topic> topicsById = BuildTopicIndex();

    private static Topic[] CombineTopics(Topic[] existingTopics, Topic[] additionalTopics)
    {
        Topic[] combined = new Topic[existingTopics.Length + additionalTopics.Length];
        Array.Copy(existingTopics, combined, existingTopics.Length);
        Array.Copy(additionalTopics, 0, combined, existingTopics.Length, additionalTopics.Length);
        return combined;
    }

    public static bool TryGetTopic(string id, out Topic topic)
    {
        if (id == null)
        {
            topic = null;
            return false;
        }

        return topicsById.TryGetValue(id, out topic);
    }

    public static Topic GetTopic(string id)
    {
        if (!TryGetTopic(id, out Topic topic))
        {
            throw new ArgumentException("Unknown vocabulary topic: " + id, nameof(id));
        }

        return topic;
    }

    public static Word[] GetWords(string id)
    {
        return GetTopic(id).Words;
    }

    public static int LetterCount(string term)
    {
        int count = 0;
        foreach (char character in term)
            if (char.IsLetterOrDigit(character)) count++;
        return count;
    }

    public static string PronunciationResourceName(string word)
    {
        bool isSimpleWord = true;
        foreach (char character in word)
        {
            if ((character < 'a' || character > 'z') && (character < 'A' || character > 'Z'))
            {
                isSimpleWord = false;
                break;
            }
        }

        if (isSimpleWord)
        {
            return word.ToLowerInvariant();
        }

        System.Text.StringBuilder slug = new System.Text.StringBuilder();
        bool previousWasSeparator = false;
        foreach (char character in word)
        {
            if (char.IsLetterOrDigit(character))
            {
                slug.Append(char.ToLowerInvariant(character));
                previousWasSeparator = false;
            }
            else if (!previousWasSeparator && slug.Length > 0)
            {
                slug.Append('_');
                previousWasSeparator = true;
            }
        }
        if (slug.Length > 0 && slug[slug.Length - 1] == '_')
        {
            slug.Length--;
        }

        uint hash = 2166136261;
        unchecked
        {
            foreach (char character in word)
            {
                hash = (hash ^ character) * 16777619;
            }
        }

        return "WorkVocabulary/" + slug + "_" + hash.ToString("x8");
    }

    private static Dictionary<string, Topic> BuildTopicIndex()
    {
        Dictionary<string, Topic> index = new Dictionary<string, Topic>(StringComparer.Ordinal);
        foreach (Topic topic in Topics)
        {
            if (index.ContainsKey(topic.Id))
            {
                throw new InvalidOperationException("Duplicate vocabulary topic id: " + topic.Id);
            }

            index.Add(topic.Id, topic);
        }

        return index;
    }

    private static Topic Create(string id, string displayName, string[] rows, string[] additionalExampleRows)
    {
        if (additionalExampleRows.Length != rows.Length)
        {
            throw new InvalidOperationException("Every vocabulary row must have four additional examples.");
        }

        Word[] words = new Word[rows.Length];
        for (int i = 0; i < rows.Length; i++)
        {
            string[] fields = (rows[i] + "|" + additionalExampleRows[i]).Split('|');
            if (fields.Length != 7)
            {
                throw new InvalidOperationException("Vocabulary rows must contain a word, meaning, and five examples.");
            }

            words[i] = new Word(fields[0], fields[1], fields[2], fields[3], fields[4], fields[5], fields[6]);
        }

        return new Topic(id, displayName, words);
    }

    public static string InferPartOfSpeech(string text, string example)
    {
        var term = NormalizeForPartOfSpeech(text);
        var sentence = " " + NormalizeForPartOfSpeech(example) + " ";
        if (string.IsNullOrEmpty(term)) return "n";

        var termWithSpaces = " " + term + " ";
        var termIndex = sentence.IndexOf(termWithSpaces, StringComparison.Ordinal);
        var before = termIndex < 0 ? string.Empty : sentence.Substring(0, termIndex).TrimEnd();
        var previousWord = LastWord(before);
        var previousTwoWords = LastTwoWords(before);
        var after = termIndex < 0 ? string.Empty
            : sentence.Substring(termIndex + termWithSpaces.Length).TrimStart();
        var nextWord = FirstWord(after);

        if (IsCommonAdjective(term)) return "adj";
        if (term.EndsWith("ly", StringComparison.Ordinal)
            && term != "family" && term != "assembly" && term != "supply"
            && term != "apply" && term != "daily" && term != "likely" && term != "friendly")
            return "adv";
        if (IsNounContext(previousWord)) return "n";
        if (IsAdjectiveSuffix(term) || IsCopula(previousWord)) return "adj";

        if (IsVerbContext(previousWord, previousTwoWords) || IsCommonVerb(term))
            return "v";
        if (IsNounSuffix(term)) return "n";
        if (string.IsNullOrEmpty(previousWord) && !string.IsNullOrEmpty(nextWord))
            return "v";
        return "n";
    }

    private static string NormalizeForPartOfSpeech(string value)
    {
        var normalized = value.ToLowerInvariant();
        var characters = normalized.ToCharArray();
        for (var index = 0; index < characters.Length; index++)
        {
            if (!char.IsLetterOrDigit(characters[index]))
                characters[index] = ' ';
        }
        return new string(characters);
    }

    private static string LastWord(string value)
    {
        var separator = value.LastIndexOf(' ');
        return separator < 0 ? value : value.Substring(separator + 1);
    }

    private static string LastTwoWords(string value)
    {
        var separator = value.LastIndexOf(' ');
        if (separator <= 0) return value;
        var previousSeparator = value.LastIndexOf(' ', separator - 1);
        return value.Substring(previousSeparator + 1);
    }

    private static string FirstWord(string value)
    {
        var separator = value.IndexOf(' ');
        return separator < 0 ? value : value.Substring(0, separator);
    }

    private static bool IsVerbContext(string previousWord, string previousTwoWords)
    {
        return previousWord == "to" || previousWord == "can" || previousWord == "could"
            || previousWord == "will" || previousWord == "would" || previousWord == "should"
            || previousWord == "must" || previousWord == "may" || previousWord == "might"
            || previousWord == "please" || previousWord == "do" || previousWord == "does"
            || previousWord == "did" || previousTwoWords == "let us";
    }

    private static bool IsNounContext(string previousWord)
    {
        return previousWord == "a" || previousWord == "an" || previousWord == "the"
            || previousWord == "this" || previousWord == "that" || previousWord == "these"
            || previousWord == "those" || previousWord == "my" || previousWord == "your"
            || previousWord == "our" || previousWord == "their" || previousWord == "each"
            || previousWord == "every";
    }

    private static bool IsCopula(string word)
    {
        return word == "is" || word == "are" || word == "was" || word == "were"
            || word == "be" || word == "become" || word == "seem" || word == "feel"
            || word == "look" || word == "remain";
    }

    private static bool IsAdjectiveSuffix(string term)
    {
        return term.EndsWith("able", StringComparison.Ordinal)
            || term.EndsWith("ible", StringComparison.Ordinal)
            || term.EndsWith("ful", StringComparison.Ordinal)
            || term.EndsWith("less", StringComparison.Ordinal)
            || term.EndsWith("ous", StringComparison.Ordinal)
            || term.EndsWith("ive", StringComparison.Ordinal)
            || term.EndsWith("ish", StringComparison.Ordinal);
    }

